class Solution {
    void pushLeft(TreeNode* node, vector<TreeNode*>& stk) {
        while (node) {
            stk.push_back(node);
            node = node->left;
        }
    }

    void pushRight(TreeNode* node, vector<TreeNode*>& stk) {
        while (node) {
            stk.push_back(node);
            node = node->right;
        }
    }

    int next(vector<TreeNode*>& stk) {
        TreeNode* node = stk.back();
        stk.pop_back();
        pushLeft(node->right, stk);
        return node->val;
    }

    int prev(vector<TreeNode*>& stk) {
        TreeNode* node = stk.back();
        stk.pop_back();
        pushRight(node->left, stk);
        return node->val;
    }

public:
    bool findTarget(TreeNode* root, int k) {
        vector<TreeNode*> nxt_stk;
        vector<TreeNode*> prv_stk;

        pushLeft(root, nxt_stk);
        pushRight(root, prv_stk);

        int l = next(nxt_stk);
        int r = prev(prv_stk);

        while (l < r) {
            int sum = l + r;
            if (sum == k) return true;
            if (sum < k) l = next(nxt_stk);
            else r = prev(prv_stk);
        }
        return false;
    }
};
